enum FddJob__ {
    static func signIn(_ request: Any?, _ deps: Any?) async throws -> Any? {
        let __f = FddVerify.frame("bp-auth-login")
        try __f.enter("NODE-AUTH-LOGIN-001")
        let email: Any? = get(get(request, "body"), "email")
        let emailCheck: Any? = checkEmail(email, "email")
        let password: Any? = get(get(request, "body"), "password")
        try __f.enter("NODE-AUTH-LOGIN-006")
        if !(bool(get(emailCheck, "valid")) && !isEmpty(password)) {
            try __f.enter("NODE-AUTH-LOGIN-009")
            return obj(
                "status", 401.0,
                "body", obj(
                    "error", bool(get(emailCheck, "valid")) ? get(checkRequired(password, "password"), "message") : get(emailCheck, "message")
                )
            )
        }
        try __f.enter("NODE-AUTH-LOGIN-010")
        let lookUpUser: Any? = try await FddVerify.dep("userService", "getUsersByEmail", "NODE-AUTH-LOGIN-010", obj("query", omitNulls(obj("email", email))))
        let status1: Any? = get(lookUpUser, "status")
        if eq(status1, 200.0) {
            try __f.enter("NODE-AUTH-LOGIN-014")
            if !eq(get(get(lookUpUser, "body"), "passwordHash"), format("hash:{password}", obj("password", password))) {
                try __f.enter("NODE-AUTH-LOGIN-021")
                return obj("status", 401.0, "body", obj("error", "Invalid credentials"))
            }
            let id: Any? = get(get(lookUpUser, "body"), "id")
            try __f.enter("NODE-AUTH-LOGIN-018")
            _ = try await FddVerify.dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", obj("userId", id))
            try __f.enter("NODE-AUTH-LOGIN-019")
            return obj(
                "status", 200.0,
                "body", obj(
                    "accessToken", format("TEST-TOKEN-{id}", obj("id", id)),
                    "refreshToken", "REFRESH-TOKEN",
                    "expiresIn", 3600.0,
                    "tokenType", "Bearer"
                )
            )
        } else if eq(status1, 404.0) {
            try __f.enter("NODE-AUTH-LOGIN-022")
            return obj("status", 401.0, "body", obj("error", "Invalid credentials"))
        } else {
            try __f.enter("NODE-AUTH-LOGIN-023")
            throw FddError("UPSTREAM_ERROR", "User Service failed")
        }
    }
}

